package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	var x int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	if _, err := fmt.Fscan(in, &x); err != nil {
		return
	}

	// The swaps repeat every 6 moves.
	nMod := int(n % 6)

	pos := x
	for i := nMod; i > 0; i-- {
		if i%2 == 1 {
			// odd move: swap 0 and 1
			if pos == 0 {
				pos = 1
			} else if pos == 1 {
				pos = 0
			}
		} else {
			// even move: swap 1 and 2
			if pos == 1 {
				pos = 2
			} else if pos == 2 {
				pos = 1
			}
		}
	}

	fmt.Println(pos)
}
