package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	var x int
	fmt.Fscan(in, &n, &x)

	// The pattern of positions repeats every 6 moves.
	nMod := int(n % 6)

	// Precomputed final positions for each initial position and n % 6.
	// rows: initial position 0,1,2
	// cols: n % 6 = 0..5
	table := [3][6]int{
		{0, 1, 2, 1, 2, 0},
		{1, 0, 0, 2, 2, 1},
		{2, 2, 1, 0, 1, 0},
	}

	for init := 0; init < 3; init++ {
		if table[init][nMod] == x {
			fmt.Println(init)
			return
		}
	}
}
